import { useTranslation } from 'react-i18next';
import { Equipment } from '@haccp/api-client';
import { getTemperatureStatusClass, checkTemperatureRange, formatTemperature } from '@/utils/temperature';

interface TemperatureStatusProps {
  temperature: number;
  equipment: Equipment;
  compact?: boolean;
}

export function TemperatureStatus({ temperature, equipment, compact = false }: TemperatureStatusProps) {
  const { t } = useTranslation();
  const check = checkTemperatureRange(temperature, equipment.minTempC, equipment.maxTempC);
  const statusClass = getTemperatureStatusClass(temperature, equipment.minTempC, equipment.maxTempC);

  if (compact) {
    return (
      <div className={`inline-flex items-center px-2 py-1 rounded text-xs font-medium border ${statusClass}`}>
        {formatTemperature(temperature)}
      </div>
    );
  }

  return (
    <div className={`p-3 rounded-lg border ${statusClass}`}>
      <div className="flex items-center justify-between mb-1">
        <span className="font-semibold">{equipment.name}</span>
        <span className="text-lg font-bold">{formatTemperature(temperature)}</span>
      </div>
      <div className="text-sm opacity-75">
        {t('tempStatus.range', { min: formatTemperature(equipment.minTempC), max: formatTemperature(equipment.maxTempC) })}
      </div>
      {check.error && <div className="text-sm mt-2">{check.error}</div>}
    </div>
  );
}
