import { useTranslation } from 'react-i18next';
import { TemperatureLog, Equipment } from '@haccp/api-client';
import {
  LineChart,
  Line,
  ReferenceLine,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
} from 'recharts';

interface TemperatureChartProps {
  logs: TemperatureLog[];
  equipment: Equipment | null;
  height?: number;
}

export function TemperatureChart({
  logs,
  equipment,
  height = 300,
}: TemperatureChartProps) {
  const { t, i18n } = useTranslation();

  if (!equipment || logs.length === 0) {
    return (
      <div
        className="bg-neutral-50 rounded-lg border border-neutral-200 flex items-center justify-center"
        style={{ height }}
      >
        <p className="text-neutral-500">{t('tempChart.noData')}</p>
      </div>
    );
  }

  const chartData = logs
    .sort((a, b) => new Date(a.measuredAt).getTime() - new Date(b.measuredAt).getTime())
    .map((log) => ({
      time: new Date(log.measuredAt).toLocaleTimeString(i18n.language, {
        hour: '2-digit',
        minute: '2-digit',
      }),
      temperature: log.temperatureC,
      timestamp: new Date(log.measuredAt).getTime(),
    }));

  const hasOutOfRange = chartData.some(
    (d) => d.temperature < equipment.minTempC || d.temperature > equipment.maxTempC
  );

  return (
    <div className="bg-white rounded-lg border border-neutral-200 p-4">
      <div className="mb-4">
        <h3 className="font-semibold text-neutral-900">{equipment.name} - {t('tempChart.trend')}</h3>
        <p className="text-sm text-neutral-600">
          {t('tempChart.range', { min: equipment.minTempC, max: equipment.maxTempC })}
          {hasOutOfRange && (
            <span className="ml-2 inline-block px-2 py-1 bg-error/10 text-error rounded text-xs font-medium">
              {t('tempChart.outOfRange')}
            </span>
          )}
        </p>
      </div>

      <ResponsiveContainer width="100%" height={height}>
        <LineChart data={chartData} margin={{ top: 5, right: 30, left: 0, bottom: 5 }}>
          <CartesianGrid strokeDasharray="3 3" stroke="#e5e7eb" />
          <XAxis
            dataKey="time"
            stroke="#6b7280"
            style={{ fontSize: '12px' }}
            tick={{ fill: '#6b7280' }}
          />
          <YAxis
            stroke="#6b7280"
            style={{ fontSize: '12px' }}
            tick={{ fill: '#6b7280' }}
            label={{
              value: t('tempChart.tempLabel'),
              angle: -90,
              position: 'insideLeft',
            }}
          />
          <Tooltip
            contentStyle={{
              backgroundColor: '#ffffff',
              border: '1px solid #e5e7eb',
              borderRadius: '6px',
            }}
            formatter={(value: any) => [`${Number(value).toFixed(1)}°C`, t('tempChart.tempSeries')]}
          />
          <Legend />

          <ReferenceLine
            y={equipment.minTempC}
            stroke="#10b981"
            strokeDasharray="5 5"
            label={{ value: `Min (${equipment.minTempC}°C)`, position: 'right', fill: '#059669' }}
          />
          <ReferenceLine
            y={equipment.maxTempC}
            stroke="#10b981"
            strokeDasharray="5 5"
            label={{ value: `Max (${equipment.maxTempC}°C)`, position: 'right', fill: '#059669' }}
          />

          <Line
            type="monotone"
            dataKey="temperature"
            stroke="#3b82f6"
            dot={(props: any) => {
              const { cx, cy, payload } = props;
              const isOutOfRange =
                payload.temperature < equipment.minTempC ||
                payload.temperature > equipment.maxTempC;
              return (
                <circle
                  cx={cx}
                  cy={cy}
                  r={4}
                  fill={isOutOfRange ? '#ef4444' : '#3b82f6'}
                />
              );
            }}
            isAnimationActive={true}
            name={t('tempChart.tempSeries')}
          />
        </LineChart>
      </ResponsiveContainer>
    </div>
  );
}
