import { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { useApiClient } from '@/hooks/useApiClient';
import { useToast } from '@/contexts/ToastContext';
import { TemperatureEntryForm } from '@/components/TemperatureEntryForm';
import { TemperatureChart } from '@/components/TemperatureChart';
import { TemperatureStatus } from '@/components/TemperatureStatus';
import { formatTemperature } from '@/utils/temperature';
import { useTranslation } from 'react-i18next';

export default function TemperatureLogsPage() {
  const apiClient = useApiClient();
  const queryClient = useQueryClient();
  const { addToast } = useToast();
  const { t, i18n } = useTranslation();
  const [selectedFilterId, setSelectedFilterId] = useState<string>('all');
  const [logsPage, setLogsPage] = useState(0);

  const REFRESH_INTERVAL = 30 * 1000;
  const LOGS_PER_PAGE = 10;

  const {
    data: equipmentList,
    isLoading: equipmentLoading,
    error: equipmentError,
  } = useQuery({
    queryKey: ['equipment'],
    queryFn: async () => {
      const all = await apiClient.getEquipment();
      return all.filter((e: any) => e.type !== 'Friteuse');
    },
    refetchInterval: REFRESH_INTERVAL,
  });

  const {
    data: temperatureLogs,
    isLoading: logsLoading,
    error: logsError,
  } = useQuery({
    queryKey: ['temperature-logs', logsPage],
    queryFn: () => apiClient.getTemperatureLogs(logsPage * LOGS_PER_PAGE, LOGS_PER_PAGE),
    refetchInterval: REFRESH_INTERVAL,
  });

  const createLogMutation = useMutation({
    mutationFn: (data: { equipmentId: string; temperatureC: number; measuredAt: string }) =>
      apiClient.createTemperatureLog(data.equipmentId, data.temperatureC, data.measuredAt),
    onSuccess: (response: any) => {
      if (response.incidentCreated) {
        addToast(t('temperature.recordedWithIncident'), 'warning');
        queryClient.invalidateQueries({ queryKey: ['incidents'] });
      } else {
        addToast(t('temperature.recorded'), 'success');
      }
      queryClient.invalidateQueries({ queryKey: ['temperature-logs'] });
      queryClient.invalidateQueries({ queryKey: ['dashboard-summary'] });
    },
    onError: (error: any) => {
      const message = error.response?.data?.message || t('temperature.recordError');
      addToast(message, 'error');
    },
  });

  const selectedEquipment = selectedFilterId === 'all' ? null : equipmentList?.find((e) => e.id === selectedFilterId);

  // Filter logs based on selected equipment
  const allFilteredLogs = selectedFilterId === 'all'
    ? (temperatureLogs?.data || [])
    : temperatureLogs?.data?.filter((log: any) => log.equipmentId === selectedFilterId) || [];

  // For display: show most recent first
  const displayedLogs = allFilteredLogs.slice().reverse().slice(0, 10);

  const latestLog = allFilteredLogs.length > 0 ? allFilteredLogs[0] : null;
  const hasMoreLogs = (temperatureLogs?.total ?? 0) > LOGS_PER_PAGE;

  const isInRange = (temp: number, equip: any) => {
    return temp >= equip.minTempC && temp <= equip.maxTempC;
  };

  if (equipmentError) {
    return (
      <div className="p-6 bg-gradient-to-r from-accent-red/10 to-red-50 border-l-4 border-accent-red rounded-lg">
        <div className="flex items-center gap-3">
          <svg className="w-6 h-6 text-accent-red" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
          </svg>
          <span className="text-accent-red font-semibold">{t('temperature.loadEquipmentError')}</span>
        </div>
      </div>
    );
  }

  if (logsError) {
    return (
      <div className="p-6 bg-gradient-to-r from-accent-red/10 to-red-50 border-l-4 border-accent-red rounded-lg">
        <div className="flex items-center gap-3">
          <svg className="w-6 h-6 text-accent-red" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
          </svg>
          <span className="text-accent-red font-semibold">{t('temperature.loadLogsError')}</span>
        </div>
      </div>
    );
  }

  const showLoading = equipmentLoading || logsLoading;

  return (
    <div className="space-y-6">
      <div className="mb-6 animate-slide-in">
        <div className="flex flex-col sm:flex-row sm:items-center gap-4">
          <div className="w-12 h-12 sm:w-14 sm:h-14 rounded-xl bg-gradient-to-br from-primary-500 to-primary-600 flex items-center justify-center shadow-lg">
            <svg className="w-7 h-7 sm:w-8 sm:h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" />
            </svg>
          </div>
          <div>
            <h1 className="text-2xl sm:text-4xl font-bold bg-gradient-to-r from-brand-dark to-primary-600 bg-clip-text text-transparent">{t('temperature.title')}</h1>
            <p className="text-neutral-600 mt-1 font-medium">{t('temperature.subtitle')}</p>
          </div>
        </div>
      </div>

      {equipmentList && equipmentList.length > 0 && !showLoading && (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-5 animate-fade-in">
          <div className="rounded-xl border-l-4 border-primary-500 p-5 sm:p-6 shadow-lg hover:shadow-xl transition-all duration-300 bg-gradient-to-br from-white via-primary-50/30 to-primary-100/20">
            <p className="text-xs font-bold text-neutral-600 uppercase tracking-wider">{t('temperature.totalReadings')}</p>
            <div className="flex items-center gap-3 mt-3">
              <svg className="w-8 h-8 text-primary-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 17v-2m3 2v-4m3 4v-6m2 10H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
              </svg>
              <p className="text-2xl sm:text-3xl font-bold text-neutral-900">{allFilteredLogs.length}</p>
            </div>
          </div>

          <div className="rounded-xl border-l-4 border-accent-green p-5 sm:p-6 shadow-lg hover:shadow-xl transition-all duration-300 bg-gradient-to-br from-white via-accent-green/5 to-green-100/20">
            <p className="text-xs font-bold text-neutral-600 uppercase tracking-wider">{t('temperature.conformReadings')}</p>
            <div className="flex items-center gap-3 mt-3">
              <svg className="w-8 h-8 text-accent-green" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
              </svg>
              <p className="text-2xl sm:text-3xl font-bold text-accent-green">
                {allFilteredLogs.filter((log: any) => log.conformity === 'OK').length}
              </p>
            </div>
          </div>

          <div className="rounded-xl border-l-4 border-accent-red p-5 sm:p-6 shadow-lg hover:shadow-xl transition-all duration-300 bg-gradient-to-br from-white via-accent-red/5 to-red-100/20">
            <p className="text-xs font-bold text-neutral-600 uppercase tracking-wider">{t('temperature.outOfRangeReadings')}</p>
            <div className="flex items-center gap-3 mt-3">
              <svg className="w-8 h-8 text-accent-red" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
              </svg>
              <p className="text-2xl sm:text-3xl font-bold text-accent-red">
                {allFilteredLogs.filter((log: any) => log.conformity === 'OUT_OF_RANGE').length}
              </p>
            </div>
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-1">
          <div className="bg-gradient-to-br from-white via-neutral-50 to-neutral-100 rounded-xl border border-neutral-200 p-5 sm:p-7 lg:sticky lg:top-6 shadow-lg hover:shadow-xl transition-all duration-300">
            <div className="flex items-center gap-3 mb-6">
              <div className="w-10 h-10 rounded-lg bg-gradient-to-br from-accent-green to-green-500 flex items-center justify-center">
                <svg className="w-5 h-5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
                </svg>
              </div>
              <h2 className="text-xl font-bold text-neutral-900">{t('temperature.quickEntry')}</h2>
            </div>
            {equipmentLoading ? (
              <div className="py-8 text-center text-neutral-500 font-medium">
                <svg className="animate-spin w-8 h-8 mx-auto text-primary-500 mb-3" fill="none" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg>
                {t('temperature.loadingEquipment')}
              </div>
            ) : equipmentList && equipmentList.length > 0 ? (
              <TemperatureEntryForm
                equipment={equipmentList}
                onSubmit={async (equipmentId, temperatureC) => {
                  await createLogMutation.mutateAsync({
                    equipmentId,
                    temperatureC,
                    measuredAt: new Date().toISOString(),
                  });
                }}
                isLoading={createLogMutation.isPending}
              />
            ) : (
              <div className="py-8 text-center">
                <div className="w-16 h-16 mx-auto mb-4 rounded-full bg-neutral-100 flex items-center justify-center">
                  <svg className="w-8 h-8 text-neutral-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 3v2m6-2v2M9 19v2m6-2v2M5 9H3m2 6H3m18-6h-2m2 6h-2M7 19h10a2 2 0 002-2V7a2 2 0 00-2-2H7a2 2 0 00-2 2v10a2 2 0 002 2zM9 9h6v6H9V9z" />
                  </svg>
                </div>
                <p className="text-neutral-600 text-sm mb-4 font-medium">{t('temperature.noEquipment')}</p>
                <a href="/equipment" className="inline-flex items-center gap-2 px-5 py-3 bg-gradient-to-r from-primary-600 to-primary-500 text-white rounded-xl font-semibold hover:from-primary-700 hover:to-primary-600 hover:shadow-lg transition-all duration-300">
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
                  </svg>
                  {t('temperature.addEquipment')}
                </a>
              </div>
            )}
          </div>
        </div>

        <div className="lg:col-span-2 space-y-6">
          <div className="bg-gradient-to-br from-white via-neutral-50 to-neutral-100 rounded-xl border border-neutral-200 p-5 sm:p-6 shadow-lg hover:shadow-xl transition-all duration-300">
            <label className="block text-sm font-bold text-neutral-900 mb-3 flex items-center gap-2">
              <svg className="w-5 h-5 text-primary-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 4a1 1 0 011-1h16a1 1 0 011 1v2.586a1 1 0 01-.293.707l-6.414 6.414a1 1 0 00-.293.707V17l-4 4v-6.586a1 1 0 00-.293-.707L3.293 7.293A1 1 0 013 6.586V4z" />
              </svg>
              {t('temperature.filterByEquipment')}
            </label>
            <select
              value={selectedFilterId}
              onChange={(e) => setSelectedFilterId(e.target.value)}
              disabled={showLoading}
              className="w-full px-4 py-3 border-2 border-neutral-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary-500 focus:border-primary-500 bg-white shadow-sm hover:shadow-md transition-all duration-300 font-medium"
            >
              <option value="all">{t('temperature.allEquipment')}</option>
              {equipmentList?.map((equip) => (
                <option key={equip.id} value={equip.id}>
                  {equip.name} ({formatTemperature(equip.minTempC)} {t('temperature.to')} {formatTemperature(equip.maxTempC)})
                </option>
              ))}
            </select>
          </div>

          {selectedEquipment && latestLog && (
            <div className={`rounded-xl border-l-4 p-5 sm:p-6 shadow-lg hover:shadow-xl transition-all duration-300 ${
              isInRange(latestLog.temperatureC, selectedEquipment)
                ? 'bg-gradient-to-br from-white via-accent-green/5 to-green-100/20 border-accent-green'
                : 'bg-gradient-to-br from-white via-accent-red/5 to-red-100/20 border-accent-red'
            }`}>
              <div className="flex items-center justify-between">
                <div>
                  <h3 className="text-sm font-bold text-neutral-600 uppercase tracking-wider mb-2">{t('temperature.latestReading')}</h3>
                  <TemperatureStatus temperature={latestLog.temperatureC} equipment={selectedEquipment} />
                  <p className="text-sm text-neutral-600 mt-3 font-medium flex items-center gap-2">
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
                    </svg>
                    {new Date(latestLog.measuredAt).toLocaleString(i18n.language)}
                  </p>
                </div>
                <div className={`w-16 h-16 rounded-full flex items-center justify-center ${
                  isInRange(latestLog.temperatureC, selectedEquipment)
                    ? 'bg-accent-green/20'
                    : 'bg-accent-red/20'
                }`}>
                  {isInRange(latestLog.temperatureC, selectedEquipment) ? (
                    <svg className="w-10 h-10 text-accent-green" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                    </svg>
                  ) : (
                    <svg className="w-10 h-10 text-accent-red" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
                    </svg>
                  )}
                </div>
              </div>
            </div>
          )}

          {selectedEquipment && !showLoading && allFilteredLogs.length > 0 && (
            <div className="bg-gradient-to-br from-white via-neutral-50 to-neutral-100 rounded-xl border border-neutral-200 p-5 sm:p-6 shadow-lg hover:shadow-xl transition-all duration-300">
              <h3 className="text-lg font-bold text-neutral-900 mb-4 flex items-center gap-2">
                <svg className="w-5 h-5 text-primary-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 12l3-3 3 3 4-4M8 21l4-4 4 4M3 4h18M4 4h16v12a1 1 0 01-1 1H5a1 1 0 01-1-1V4z" />
                </svg>
                {t('temperature.trend')}
              </h3>
              <TemperatureChart
                logs={allFilteredLogs}
                equipment={selectedEquipment}
                height={350}
              />
            </div>
          )}

          {showLoading && (
            <div className="bg-gradient-to-br from-white to-neutral-50 rounded-xl border border-neutral-200 p-12 text-center shadow-lg">
              <svg className="animate-spin w-12 h-12 mx-auto text-primary-500 mb-4" fill="none" viewBox="0 0 24 24">
                <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
              </svg>
              <p className="text-neutral-500 font-medium">{t('temperature.loadingData')}</p>
            </div>
          )}

          {selectedEquipment && !showLoading && allFilteredLogs.length > 0 && (
            <div className="bg-gradient-to-br from-white via-neutral-50 to-neutral-100 rounded-xl border border-neutral-200 p-5 sm:p-7 shadow-lg hover:shadow-xl transition-all duration-300">
              <h3 className="text-lg sm:text-xl font-bold text-neutral-900 mb-6 flex items-center gap-2">
                <svg className="w-6 h-6 text-primary-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
                </svg>
                {t('temperature.recentReadings')}
              </h3>
              <div className="space-y-3 mb-4">
                {displayedLogs.map((log: any) => {
                  const inRange = log.conformity === 'OK';
                  return (
                    <div key={log.id} className={`flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3 py-4 px-4 sm:px-5 rounded-xl border-2 transition-all duration-300 hover:shadow-md ${
                      inRange
                        ? 'bg-gradient-to-r from-white to-accent-green/5 border-accent-green/30 hover:border-accent-green'
                        : 'bg-gradient-to-r from-white to-accent-red/5 border-accent-red/30 hover:border-accent-red'
                    }`}>
                      <div className="flex items-center gap-4">
                        <div className={`w-10 h-10 rounded-full flex items-center justify-center ${
                          inRange ? 'bg-accent-green/20' : 'bg-accent-red/20'
                        }`}>
                          {inRange ? (
                            <svg className="w-5 h-5 text-accent-green" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                            </svg>
                          ) : (
                            <svg className="w-5 h-5 text-accent-red" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                            </svg>
                          )}
                        </div>
                        <div>
                          <p className={`text-lg sm:text-xl font-bold ${inRange ? 'text-accent-green' : 'text-accent-red'}`}>
                            {formatTemperature(log.temperatureC)}
                          </p>
                          <p className="text-xs text-neutral-500 font-medium">
                            {new Date(log.measuredAt).toLocaleString(i18n.language)}
                          </p>
                        </div>
                      </div>
                      <span className={`px-3 py-1 rounded-full text-xs font-bold ${
                        inRange
                          ? 'bg-accent-green/20 text-accent-green'
                          : 'bg-accent-red/20 text-accent-red'
                      }`}>
                        {inRange ? 'OK' : t('temperature.alert')}
                      </span>
                    </div>
                  );
                })}
              </div>
              {hasMoreLogs && (
                <button
                  onClick={() => setLogsPage(p => p + 1)}
                  className="w-full mt-4 px-4 py-2.5 bg-primary-50 text-primary-600 border border-primary-200 rounded-lg font-medium hover:bg-primary-100 transition-colors"
                >
                  {t('temperature.loadMore')}
                </button>
              )}
            </div>
          )}

          {!showLoading && allFilteredLogs.length === 0 && (
            <div className="bg-gradient-to-br from-white to-neutral-50 rounded-xl border border-neutral-200 p-12 text-center shadow-lg">
              <div className="w-20 h-20 mx-auto mb-4 rounded-full bg-neutral-100 flex items-center justify-center">
                <svg className="w-10 h-10 text-neutral-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" />
                </svg>
              </div>
              <p className="text-neutral-600 font-semibold">{t('temperature.noReadingsYet')}</p>
              <p className="text-neutral-500 text-sm mt-1">{t('temperature.useForm')}</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
