import { useState } from 'react';
import { Equipment } from '@haccp/api-client';
import { useTranslation } from 'react-i18next';
import { validateTemperature, checkTemperatureRange, formatTemperature } from '@/utils/temperature';
import { TemperatureStatus } from './TemperatureStatus';

interface TemperatureEntryFormProps {
  equipment: Equipment[];
  onSubmit: (equipmentId: string, temperatureC: number) => Promise<void>;
  isLoading?: boolean;
}

export function TemperatureEntryForm({
  equipment,
  onSubmit,
  isLoading = false,
}: TemperatureEntryFormProps) {
  const { t } = useTranslation();
  const [selectedEquipmentId, setSelectedEquipmentId] = useState<string>(
    equipment[0]?.id || ''
  );
  const [temperature, setTemperature] = useState('');
  const [error, setError] = useState('');
  const [preview, setPreview] = useState<{ equipment: Equipment; temp: number } | null>(null);

  const selectedEquip = equipment.find((e) => e.id === selectedEquipmentId);

  const handleTemperatureChange = (value: string) => {
    setTemperature(value);
    setError('');

    // Live preview of status
    if (value && selectedEquip) {
      const validation = validateTemperature(value);
      if (validation.isValid) {
        const tempNum = parseFloat(value);
        setPreview({ equipment: selectedEquip, temp: tempNum });
      }
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    // Validate temperature
    const tempValidation = validateTemperature(temperature);
    if (!tempValidation.isValid) {
      setError(tempValidation.error || t('temperature.invalidTemperature'));
      return;
    }

    if (!selectedEquip) {
      setError(t('temperature.selectEquipment'));
      return;
    }

    const tempNum = parseFloat(temperature);

    // Check range but don't prevent submission (just warn)
    const rangeCheck = checkTemperatureRange(tempNum, selectedEquip.minTempC, selectedEquip.maxTempC);
    if (rangeCheck.severity === 'danger') {
      const confirmSubmit = window.confirm(
        `${rangeCheck.error}\n\n${t('temperature.confirmOutOfRange')}`
      );
      if (!confirmSubmit) return;
    }

    try {
      await onSubmit(selectedEquipmentId, tempNum);
      setTemperature('');
      setPreview(null);
    } catch (err: any) {
      setError(err.response?.data?.message || t('temperature.recordError'));
    }
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-4">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        {/* Equipment Selection */}
        <div>
          <label className="block text-sm font-semibold text-neutral-900 mb-2">
            {t('temperature.equipment')}
          </label>
          <select
            value={selectedEquipmentId}
            onChange={(e) => {
              setSelectedEquipmentId(e.target.value);
              setPreview(null);
            }}
            disabled={isLoading}
            className="w-full px-4 py-2 border border-neutral-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500"
          >
            {equipment.map((equip) => (
              <option key={equip.id} value={equip.id}>
                {equip.name} ({formatTemperature(equip.minTempC)} {t('temperature.to')} {formatTemperature(equip.maxTempC)})
              </option>
            ))}
          </select>
        </div>

        {/* Temperature Input */}
        <div>
          <label className="block text-sm font-semibold text-neutral-900 mb-2">
            {t('temperature.temperature')} (°C)
          </label>
          <input
            type="number"
            step="0.1"
            value={temperature}
            onChange={(e) => handleTemperatureChange(e.target.value)}
            placeholder={t('temperature.temperaturePlaceholder')}
            disabled={isLoading}
            className="w-full px-4 py-2 border border-neutral-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500"
          />
        </div>
      </div>

      {/* Temperature Preview */}
      {preview && (
        <div>
          <label className="block text-sm font-semibold text-neutral-900 mb-2">
            {t('temperature.statusPreview')}
          </label>
          <TemperatureStatus temperature={preview.temp} equipment={preview.equipment} />
        </div>
      )}



      {/* Error */}
      {error && (
        <div className="p-3 bg-error/10 border border-error text-error rounded-lg text-sm">
          {error}
        </div>
      )}

      {/* Submit Button */}
      <button
        type="submit"
        disabled={isLoading || !temperature}
        className="w-full px-4 py-2 bg-primary-600 text-white font-semibold rounded-lg hover:bg-primary-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
      >
        {isLoading ? t('common.saving') : t('temperature.addReading')}
      </button>
    </form>
  );
}
