import { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { useApiClient } from '@/hooks/useApiClient';
import { useToast } from '@/contexts/ToastContext';
import { LoadingSpinner, PageError } from '@/components/ui';
import type { CleaningSector, CleaningEquipmentItem, CleaningTask } from '@haccp/api-client';
import { getSectorIcon, getSectorColor } from '@/utils/equipment';
import { useTranslation } from 'react-i18next';

export default function CleaningPage() {
  const apiClient = useApiClient();
  const queryClient = useQueryClient();
  const { addToast } = useToast();
  const { t, i18n } = useTranslation();
  const [expandedSectors, setExpandedSectors] = useState<Set<string>>(new Set());

  const { data, isLoading, error } = useQuery({
    queryKey: ['cleaning-today'],
    queryFn: () => apiClient.getCleaningToday(),
    refetchInterval: 30000,
  });

  const plan = data?.plan;
  const sectors = data?.sectors || [];
  const isCompleted = !!plan?.completedAt;

  let totalTasks = 0;
  let checkedTasks = 0;
  sectors.forEach((s: CleaningSector) => {
    s.subSectors?.forEach((ss) => {
      ss.equipment?.forEach((eq: CleaningEquipmentItem) => {
        eq.tasks?.forEach((t: CleaningTask) => {
          totalTasks++;
          if (t.checked) checkedTasks++;
        });
      });
    });
  });
  const progress = totalTasks > 0 ? Math.round((checkedTasks / totalTasks) * 100) : 0;
  const allChecked = totalTasks > 0 && checkedTasks === totalTasks;

  const checkMutation = useMutation({
    mutationFn: ({ taskId }: { taskId: string }) =>
      apiClient.checkCleaningTask(plan!.id, taskId),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: ['cleaning-today'] }),
    onError: (e: any) => addToast(e.response?.data?.message || t('cleaning.taskError'), 'error'),
  });

  const uncheckMutation = useMutation({
    mutationFn: ({ taskId }: { taskId: string }) =>
      apiClient.uncheckCleaningTask(plan!.id, taskId),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: ['cleaning-today'] }),
    onError: (e: any) => addToast(e.response?.data?.message || t('cleaning.taskError'), 'error'),
  });

  const completeMutation = useMutation({
    mutationFn: () => apiClient.completeCleaningPlan(plan!.id),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['cleaning-today'] });
      queryClient.invalidateQueries({ queryKey: ['dashboard-summary'] });
      addToast(t('cleaning.success'), 'success');
    },
    onError: (e: any) => addToast(e.response?.data?.message || t('cleaning.taskError'), 'error'),
  });

  const toggleSector = (id: string) => {
    const s = new Set(expandedSectors);
    s.has(id) ? s.delete(id) : s.add(id);
    setExpandedSectors(s);
  };

  const handleToggleTask = async (task: CleaningTask) => {
    if (isCompleted) return;
    if (task.checked) {
      uncheckMutation.mutate({ taskId: task.id });
    } else {
      checkMutation.mutate({ taskId: task.id });
    }
  };

  const today = new Date().toLocaleDateString(i18n.language, {
    weekday: 'long',
    day: 'numeric',
    month: 'long',
    year: 'numeric',
  });

  const isMonday = new Date().getDay() === 1;

  return (
    <div className="min-h-screen bg-gray-50">
      <div className="bg-white border-b border-gray-200">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
          <div className="flex flex-col sm:flex-row sm:items-center gap-3">
            <div className="p-3 bg-gray-100 rounded-lg">
              <span className="text-2xl">🧹</span>
            </div>
            <div>
              <h1 className="text-2xl sm:text-3xl font-bold text-gray-900">{t('cleaning.planTitle')}</h1>
              <p className="text-gray-600 mt-1 capitalize">{today}</p>
              {isMonday && (
                <p className="text-sm text-purple-600 font-medium mt-1">{t('cleaning.monday')}</p>
              )}
            </div>
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {isLoading ? (
          <LoadingSpinner message={t('cleaning.loadingPlan')} />
        ) : error ? (
          <PageError message={t('cleaning.planError')} />
        ) : sectors.length === 0 ? (
          <div className="bg-white rounded-xl shadow p-4 sm:p-8 text-center">
            <span className="text-5xl block mb-4">📋</span>
            <h2 className="text-xl font-bold text-gray-900 mb-2">{t('cleaning.noTasksTitle')}</h2>
            <p className="text-gray-500">{t('cleaning.noTasksAdmin')}</p>
          </div>
        ) : (
          <div className="space-y-6">
            {!isCompleted && (
              <div className="bg-white rounded-xl shadow p-5">
                <div className="flex items-center justify-between mb-3">
                  <span className="text-sm font-bold text-gray-700">{t('cleaning.progress')}</span>
                  <span className={`text-lg font-bold ${progress >= 100 ? 'text-green-600' : progress >= 50 ? 'text-amber-600' : 'text-blue-600'}`}>
                    {progress}%
                  </span>
                </div>
                <div className="w-full bg-gray-200 rounded-full h-3 overflow-hidden">
                  <div
                    className={`h-3 rounded-full transition-all duration-500 ${
                      progress >= 100 ? 'bg-green-500' : progress >= 50 ? 'bg-amber-500' : 'bg-blue-500'
                    }`}
                    style={{ width: `${progress}%` }}
                  />
                </div>
                <p className="text-xs text-gray-500 mt-2">{t('cleaning.tasksCompleted', { checked: checkedTasks, total: totalTasks })}</p>
              </div>
            )}

            {isCompleted && (
              <div className="bg-green-50 border-l-4 border-green-500 rounded-lg p-5 flex items-center gap-3">
                <span className="text-3xl">✅</span>
                <div>
                  <p className="font-bold text-green-800">{t('cleaning.completedBanner')}</p>
                  <p className="text-sm text-green-600">
                    {t('cleaning.completedAt', { date: new Date(plan!.completedAt!).toLocaleString(i18n.language) })}
                  </p>
                </div>
              </div>
            )}

            {sectors.map((sector: CleaningSector) => {
              const sectorChecked = sector.subSectors?.reduce((sum, ss) =>
                sum + (ss.equipment?.reduce((s2, eq) =>
                  s2 + (eq.tasks?.filter((t) => t.checked).length || 0), 0) || 0), 0) || 0;
              const sectorTotal = sector.subSectors?.reduce((sum, ss) =>
                sum + (ss.equipment?.reduce((s2, eq) =>
                  s2 + (eq.tasks?.length || 0), 0) || 0), 0) || 0;
              const sectorDone = sectorTotal > 0 && sectorChecked === sectorTotal;
              const isExpanded = expandedSectors.has(sector.id);
              const icon = getSectorIcon(sector.name);
              const color = getSectorColor(sector.name);

              return (
                <div key={sector.id} className={`bg-white rounded-xl shadow overflow-hidden border-l-4 ${sectorDone ? 'border-l-green-400' : color.border}`}>
                  <div
                    className={`flex items-center justify-between p-5 cursor-pointer transition ${
                      sectorDone ? 'bg-green-50/50' : 'hover:bg-gray-50'
                    }`}
                    onClick={() => toggleSector(sector.id)}
                  >
                    <div className="flex items-center gap-3">
                      <span className={`transform transition-transform ${isExpanded ? 'rotate-90' : ''}`}>▶</span>
                      <span className="text-xl">{icon}</span>
                      <h3 className="text-lg font-semibold text-gray-900">{sector.name}</h3>
                      {sectorDone && <span className="text-green-600">✓</span>}
                    </div>
                    <span className={`text-sm font-medium px-3 py-1 rounded-full ${
                      sectorDone ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-600'
                    }`}>
                      {sectorChecked}/{sectorTotal}
                    </span>
                  </div>

                  {isExpanded && (
                    <div className="border-t border-gray-200 p-5 space-y-5">
                      {sector.subSectors?.flatMap((ss) => ss.equipment || []).map((eq: CleaningEquipmentItem) => (
                        <div key={eq.id}>
                          <h4 className="font-semibold text-gray-700 mb-3 flex items-center gap-2">
                            <span className="text-base">🔧</span> {eq.name}
                          </h4>
                          <div className="space-y-2">
                            {eq.tasks?.map((task: CleaningTask) => (
                              <label
                                key={task.id}
                                className={`flex items-center gap-3 p-3 rounded-lg border-2 cursor-pointer transition ${
                                  task.checked
                                    ? 'bg-green-50 border-green-300'
                                    : 'bg-white border-gray-200 hover:border-blue-300 hover:bg-blue-50/30'
                                } ${isCompleted ? 'cursor-not-allowed opacity-75' : ''}`}
                              >
                                <input
                                  type="checkbox"
                                  checked={!!task.checked}
                                  onChange={() => handleToggleTask(task)}
                                  disabled={isCompleted || checkMutation.isPending || uncheckMutation.isPending}
                                  className="w-5 h-5 text-green-600 rounded border-gray-300 focus:ring-green-500"
                                />
                                <span className={`flex-1 text-sm ${task.checked ? 'text-green-700 line-through' : 'text-gray-800'}`}>
                                  {task.name}
                                </span>
                                <span className={`text-xs px-2 py-0.5 rounded-full font-medium ${
                                  task.frequency === 'DAILY' ? 'bg-green-100 text-green-700' : 'bg-purple-100 text-purple-700'
                                }`}>
                                  {task.frequency === 'DAILY' ? t('cleaning.daily') : t('cleaning.weekly')}
                                </span>
                                {task.check && (
                                  <span className="text-xs text-gray-400">
                                    {task.check.checkedBy?.displayName || task.check.checkedBy?.email}
                                  </span>
                                )}
                              </label>
                            ))}
                          </div>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              );
            })}

            {!isCompleted && (
              <button
                onClick={() => completeMutation.mutate()}
                disabled={!allChecked || completeMutation.isPending}
                className={`w-full py-4 rounded-xl font-bold text-lg transition-all ${
                  allChecked
                    ? 'bg-green-600 text-white hover:bg-green-700 shadow-lg hover:shadow-xl'
                    : 'bg-gray-300 text-gray-500 cursor-not-allowed'
                }`}
              >
                {completeMutation.isPending
                  ? t('cleaning.completing')
                  : allChecked
                    ? t('cleaning.validateButton')
                    : t('cleaning.tasksRemaining', { count: totalTasks - checkedTasks })}
              </button>
            )}
          </div>
        )}
      </div>
    </div>
  );
}
